import { retryAfterMillis } from '../time/retryAfter';

export function chooseDeliveryRetry(attempt: number, status: number, retryAfter: string | undefined, nowMs: number) {
  if (status !== 429 && status < 500) return { kind: 'stop' as const };
  if (attempt >= 5) return { kind: 'stop' as const };
  const exponentialMs = Math.min(1000 * 2 ** attempt, 60000);
  const serverHintMs = status === 429 ? retryAfterMillis(retryAfter) : 0;
  const delayMs = Math.max(exponentialMs, serverHintMs);
  return { kind: 'retry' as const, delayMs, dueAtMs: nowMs + delayMs };
}

