import { handleFailure } from './handleFailure';
import { postPayload } from '../transport/http';
import type { DeliveryQueue, DeliveryJob } from '../storage/deliveryQueue';

export async function deliver(job: DeliveryJob, queue: DeliveryQueue, nowMs: number) {
  const response = await postPayload(job.url, job.payload);
  if (response.status >= 200 && response.status < 300) {
    await queue.complete(job.id);
    return { kind: 'complete' as const };
  }
  return handleFailure(job, response, queue, nowMs);
}

