import { chooseDeliveryRetry } from '../policies/deliveryRetry';
import type { DeliveryQueue, DeliveryJob } from '../storage/deliveryQueue';
import type { HttpResponse } from '../transport/http';

export async function handleFailure(job: DeliveryJob, response: HttpResponse, queue: DeliveryQueue, nowMs: number) {
  const decision = chooseDeliveryRetry(job.attempt, response.status, response.headers['retry-after'], nowMs);
  if (decision.kind === 'retry') {
    await queue.reschedule(job.id, decision.dueAtMs);
  } else {
    await queue.deadLetter(job.id);
  }
  return decision;
}

