import type { Lease } from '../storage/leaseStore';

export function evaluateRenewal(current: Lease, input: { owner: string; expectedGeneration: number }, nowMs: number) {
  if (current.expiresAtMs <= nowMs) return { ok: false as const, code: 'EXPIRED' as const };
  if (current.owner !== input.owner) return { ok: false as const, code: 'OWNER_MISMATCH' as const };
  if (current.generation !== input.expectedGeneration) return { ok: false as const, code: 'STALE_GENERATION' as const };
  return { ok: true as const };
}

