import { renewLease } from '../services/renewLease';
import type { LeaseStore } from '../storage/leaseStore';

export async function renewLeaseHandler(request: { id: string; owner: string; expectedGeneration: number; ttlMs: number }, store: LeaseStore, nowMs: number) {
  const result = await renewLease(request, store, nowMs);
  if (result.ok) return { status: 200, body: result.lease };
  const status = result.code === 'NOT_FOUND' ? 404 : result.code === 'OWNER_MISMATCH' ? 403 : 409;
  return { status, body: { error: result.code } };
}

