import { evaluateRenewal } from '../policies/renewal';
import type { LeaseStore } from '../storage/leaseStore';

export async function renewLease(input: { id: string; owner: string; expectedGeneration: number; ttlMs: number }, store: LeaseStore, nowMs: number) {
  const current = await store.get(input.id);
  if (!current) return { ok: false as const, code: 'NOT_FOUND' as const };
  const decision = evaluateRenewal(current, input, nowMs);
  if (!decision.ok) return decision;
  const renewed = { ...current, generation: current.generation + 1, expiresAtMs: nowMs + input.ttlMs };
  await store.put(input.id, renewed);
  return { ok: true as const, lease: renewed };
}

