export function chargeUnusedPeriod(remainingDays: number, periodDays: number, monthlyCents: number) {
  if (periodDays <= 0) throw new Error('INVALID_PERIOD');
  if (remainingDays <= 0) return 0;
  const billableDays = Math.min(remainingDays, periodDays);
  return Math.ceil(monthlyCents * billableDays / periodDays);
}

