import { transition } from '../core/state';
export function holdJob(id: string, owner: string, expectedRevision: number, repository: { get(id: string): any; put(id: string, row: any): void }) {
  const current = repository.get(id);
  const result = transition(current, owner, expectedRevision);
  if (result.ok) repository.put(id, result.row);
  return result;
}

