export function transition(current: { owner: string; revision: number; active: boolean }, owner: string, expectedRevision: number) {
  if (current.owner !== owner) return { ok: false, reason: 'WRONG_OWNER' };
  if (current.revision !== expectedRevision) return { ok: false, reason: 'STALE_REVISION' };
  return { ok: true, row: { ...current, active: false, revision: current.revision + 1 } };
}

